changeSet.sql:
ALTER TABLE ${ARENA_DB_SCHEMA}.customer ADD COLUMN training_timezone VARCHAR(80) NOT NULL DEFAULT 'Asia/Kolkata', ADD COLUMN training_setup_skipped BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE ${ARENA_DB_SCHEMA}.sport_catalogue (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, created_by VARCHAR(100), updated_by VARCHAR(100), code VARCHAR(64) NOT NULL UNIQUE, label VARCHAR(160) NOT NULL, facility_kind VARCHAR(12), active BOOLEAN NOT NULL);
CREATE TABLE ${ARENA_DB_SCHEMA}.academy_sport (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, created_by VARCHAR(100), updated_by VARCHAR(100), academy_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.customer(id), catalogue_code VARCHAR(64) REFERENCES ${ARENA_DB_SCHEMA}.sport_catalogue(code), name VARCHAR(160) NOT NULL, registration_key VARCHAR(180) NOT NULL, training BOOLEAN NOT NULL, sessions BOOLEAN NOT NULL, active BOOLEAN NOT NULL, UNIQUE(academy_id, registration_key), UNIQUE(id, academy_id), CHECK(training OR sessions));
CREATE TABLE ${ARENA_DB_SCHEMA}.academy_staff (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, created_by VARCHAR(100), updated_by VARCHAR(100), academy_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.customer(id), app_user_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.app_user(id), name VARCHAR(160) NOT NULL, email VARCHAR(255) NOT NULL, phone VARCHAR(50), role VARCHAR(20) NOT NULL CHECK(role IN ('COACH','STAFF')), active BOOLEAN NOT NULL, UNIQUE(academy_id, app_user_id), UNIQUE(id, academy_id));
CREATE TABLE ${ARENA_DB_SCHEMA}.training_batch (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, created_by VARCHAR(100), updated_by VARCHAR(100), academy_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.customer(id), sport_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, code VARCHAR(64) NOT NULL, level VARCHAR(100), capacity INTEGER CHECK(capacity > 0), start_date DATE NOT NULL, end_date DATE, status VARCHAR(16) NOT NULL CHECK(status IN ('DRAFT','ACTIVE','INACTIVE')), lead_coach_id BIGINT, UNIQUE(academy_id, code), UNIQUE(id, academy_id), FOREIGN KEY(sport_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_sport(id,academy_id), FOREIGN KEY(lead_coach_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_staff(id,academy_id), CHECK(end_date IS NULL OR end_date >= start_date));
CREATE TABLE ${ARENA_DB_SCHEMA}.batch_schedule (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, created_by VARCHAR(100), updated_by VARCHAR(100), batch_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.training_batch(id), day_of_week INTEGER NOT NULL CHECK(day_of_week BETWEEN 1 AND 7), start_time TIME NOT NULL, end_time TIME NOT NULL, effective_from DATE NOT NULL, effective_to DATE, active BOOLEAN NOT NULL, CHECK(end_time > start_time), CHECK(effective_to IS NULL OR effective_to >= effective_from));
CREATE TABLE ${ARENA_DB_SCHEMA}.academy_staff_sport (staff_id BIGINT NOT NULL, academy_id BIGINT NOT NULL, sport_id BIGINT NOT NULL, PRIMARY KEY(staff_id,sport_id), FOREIGN KEY(staff_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_staff(id,academy_id), FOREIGN KEY(sport_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_sport(id,academy_id));
CREATE TABLE ${ARENA_DB_SCHEMA}.batch_coach (batch_id BIGINT NOT NULL, academy_id BIGINT NOT NULL, staff_id BIGINT NOT NULL, PRIMARY KEY(batch_id,staff_id), FOREIGN KEY(batch_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.training_batch(id,academy_id), FOREIGN KEY(staff_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_staff(id,academy_id));
CREATE INDEX academy_sport_scope ON ${ARENA_DB_SCHEMA}.academy_sport(academy_id,active);
CREATE INDEX academy_staff_scope ON ${ARENA_DB_SCHEMA}.academy_staff(academy_id,active,role);
CREATE INDEX training_batch_scope ON ${ARENA_DB_SCHEMA}.training_batch(academy_id,sport_id,status);
CREATE INDEX batch_schedule_lookup ON ${ARENA_DB_SCHEMA}.batch_schedule(batch_id,active,day_of_week);
CREATE INDEX batch_coach_staff ON ${ARENA_DB_SCHEMA}.batch_coach(staff_id,batch_id);
